 'use strict';
let conversationStage='welcome',conversationMode='demo',agentStatus={available:false},researchHistory=[],busy=false,requestController=null,requestVersion=0,modeTouched=false;
function scrollThread(){requestAnimationFrame(()=>{$('thread-scroll').scrollTop=$('thread-scroll').scrollHeight;});}
function message(role,text,sourceList=[]){$('welcome').hidden=true;const item=document.createElement('article');item.className='message '+role;const label=document.createElement('span');label.className='message-role';label.textContent=role==='user'?'你':conversationMode==='demo'?'来处 · 示例助手':'来处 · 溯源助手';const body=document.createElement('p');if(role==='assistant'&&sourceList.length){const lookup=new Map(sourceList.map(source=>[source.id,source]));for(const part of text.split(/(\[S\d+\])/g)){const source=lookup.get(part.slice(1,-1));const url=source&&safeUrl(source.url);if(url){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=part;a.title=source.title||'查看来源';body.append(a);}else body.append(document.createTextNode(part));}}else body.textContent=text;item.append(label,body);$('conversation').append(item);scrollThread();return item;}
function suggestions(options){$('suggestions').replaceChildren();$('suggestions').classList.toggle('compact',conversationStage!=='welcome');for(const [label,action] of options){const button=document.createElement('button');button.type='button';button.textContent=label;button.disabled=busy;button.addEventListener('click',()=>{if(busy)return;if(conversationMode==='live')submitQuestion(label);else {act(action,label);setBusy(false);}});$('suggestions').append(button);}}
function clue(title,copy,stopId,sourceList=[]){const card=document.createElement('section');card.className='clue-card';const tag=document.createElement('span');tag.className='step';tag.textContent=conversationMode==='demo'?'示例线索 · 待核查':'公开资料线索';const heading=document.createElement('h2');heading.textContent=title;const p=document.createElement('p');p.textContent=copy;card.append(tag,heading,p);if(stopId&&stops.some(s=>s.id===stopId)){const button=document.createElement('button');button.type='button';button.className='text-button';button.textContent='在地图上查看';const snapshot=stops.find(s=>s.id===stopId);button.addEventListener('click',()=>{if(!stops.includes(snapshot)){window.routeRevealed=false;setMapDataset([snapshot],[]);$('map-heading').textContent='回看这条线索';$('route-caption').textContent='前一轮查询中的地点 · 非最新查询全图';}selectStop(snapshot.id);});card.append(button);}const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='查看依据';const body=document.createElement('div');if(sourceList.length){for(const source of sourceList)linkSource(body,source);}else{const text=document.createElement('p');text.textContent=stops.find(s=>s.id===stopId)?.source||'位置尚不明确，暂不在地图上定位。';body.append(text);}details.append(summary,body);card.append(details);$('conversation').append(card);scrollThread();}
function followup(){conversationStage='generation';message('assistant','示例里有两组字辈。你听过哪一组？不知道也可以继续。');suggestions([['英、士、班、家、国','dayuan'],['英、士、中、州、启','yangxin'],['暂时不知道','unknown']]);}
function startDemo(kind){query={demo:true};branch=null;message('assistant',kind==='origin'?'我们先沿“祖上从江西来”这条说法探索。示例材料提到江西乐平，但还缺原谱，暂时只能作为迁出线索。':kind==='culture'?'同姓同乡不一定属于同一支。这个示例里，通山与阳新的两组字辈不同，可以用来演示如何进一步缩小范围。':'字辈是家族命名中的代际线索，不能直接推断某个人的父亲或祖父是谁。先用通山阮氏材料，看看它怎样帮助区分支系。');clue(kind==='origin'?'江西乐平 · 迁出线索':'通山阮氏 · 两组字辈线索',kind==='origin'?'材料提及乐平杏花村迁出说法；原村址与年份待核对。':'英士班家国 / 英士中州启，来自讨论材料，尚未核对谱页。',kind==='origin'?'leping':'tongshan');selectStop(kind==='origin'?'leping':'tongshan',true,false);followup();}
function act(action,label){message('user',label);if(['generation-demo','origin-demo','culture-demo'].includes(action)){startDemo(action.split('-')[0]);return;}
if(['dayuan','yangxin','unknown'].includes(action)){branch=action;conversationStage='candidate';window.routeRevealed=false;syncMap();const place=action==='yangxin'?'阳新':'通山';message('assistant',action==='unknown'?'我们保留两种可能，不确定所属支系。仍然可以查看材料里的迁徙说法和姓氏文化。':`所选字辈与${place}候选线索相符。这是演示匹配，还缺原谱和亲属记录，不能确认你属于该支。`);clue(action==='unknown'?'两条候选线索，暂不确定':place+' · 候选支系',action==='dayuan'?'英、士、班、家、国：通山大源候选。':action==='yangxin'?'英、士、中、州、启：阳新候选。':'字辈未知，保留通山与阳新两种可能。',action==='yangxin'?'yangxin':'tongshan');selectStop(action==='yangxin'?'yangxin':'tongshan',true,false);suggestions([['看看江西迁徙线索','route'],['竹林堂和阮籍有什么关系？','culture'],['我还需要问家里什么？','family'],['重新选择字辈','change']]);return;}
if(action==='route'){message('assistant','地图上已展开乐平、阳新、通山三处候选地点。材料称阮四一于1275年前后从乐平迁往兴国州，但古今地域、迁入村址以及通山分支年代仍待核查。虚线表示材料中的候选联系，不代表实际道路。');revealRoute();clue('三处地点 · 候选迁徙线索','点击地图地点或下方线索栏，可飞到当地查看依据。陈留仅为文化背景，不接入这条路线。','leping');}
else if(action==='culture'){message('assistant','演示材料将竹林堂与阮籍、阮咸联系起来。这可以作为姓氏文化线索，但不能证明他们是你的直系祖先；堂号来源也需要文献核对。');clue('陈留 · 姓氏文化背景','文化联系与个人血缘关系分开展示。','chenliu');selectStop('chenliu',true,false);}
else if(action==='family'){message('assistant','可以问长辈一个具体问题：“爷爷或曾祖父原来住哪个村？”如果记得姓名、字辈或旧谱里的地名，也能作为下一条线索。你可以把答案继续写在下方；这版不会保存或公开这些内容。');}
else if(action==='change'){branch=null;window.routeRevealed=false;syncMap();$('route-caption').textContent='重新核对字辈 · 候选路线暂不展开';followup();return;}
suggestions([['看看江西迁徙线索','route'],['竹林堂和阮籍有什么关系？','culture'],['我还需要问家里什么？','family'],['重新选择字辈','change']]);}

function welcomeSuggestions(){if(conversationMode==='demo'){suggestions([['阮氏示例：家里的字辈说明什么？','generation-demo'],['阮氏示例：祖上从江西来？','origin-demo'],['阮氏示例：同姓就是一家人吗？','culture-demo']]);}else{suggestions([['我想了解家族来历，需要先提供哪些线索？',''],['家里的字辈能帮助找祖籍吗？',''],['长辈说祖上迁来，怎样核查？','']]);}}
function updateServiceNotice(){ $('mode-live').setAttribute('aria-pressed',String(conversationMode==='live'));$('mode-demo').setAttribute('aria-pressed',String(conversationMode==='demo'));$('session-tag').textContent=conversationMode==='demo'?'阮氏示例':'真实溯源';$('service-notice').classList.toggle('warning',conversationMode==='live'&&!agentStatus.available);$('service-notice').textContent=conversationMode==='demo'?'预置阮氏材料演示，尚未核对原谱。':agentStatus.available?'从公开资料中查找，每条线索保留出处。':'真实溯源尚未启用。可以先切换到「体验示例」。';$('question').placeholder=conversationMode==='demo'?'选择上面的示例，或回答助手的追问…':'例如：我姓陈，祖籍福建泉州，想知道家族迁徙线索。';}
function setBusy(value){busy=value;$('query-progress').hidden=!value;$('send-question').disabled=value;$('send-question').textContent=value?'查找中…':conversationStage==='welcome'?'开始探索':'发送';document.querySelectorAll('#suggestions button').forEach(b=>b.disabled=value);}
function cancelResearch(notify=true){if(!busy)return;requestVersion++;requestController?.abort();requestController=null;setBusy(false);if(notify)message('assistant','已停止这次查找。你可以调整问题后继续。');}
function resetConversation(){cancelResearch(false);requestVersion++;query=null;branch=null;researchHistory=[];conversationStage='welcome';$('conversation').replaceChildren();$('suggestions').replaceChildren();$('question').value='';$('question').style.height='';$('form-error').hidden=true;$('welcome').hidden=false;if(conversationMode==='demo')useDemoMap();else useLiveMap();showView('chat');updateServiceNotice();welcomeSuggestions();setBusy(false);}
function switchMode(mode){if(!['demo','live'].includes(mode))return;modeTouched=true;conversationMode=mode;resetConversation();}
async function sendResearch(text,appendUser=true){if(busy)return {status:'busy'};if(appendUser)message('user',text);if(!agentStatus.available){message('assistant','真实溯源还没有启用，因此这次没有进行网络查询。可以先体验示例；服务配置完成后，就能按你的姓氏与祖籍查找公开资料。');suggestions([]);return {status:'unavailable'};}const version=++requestVersion;requestController=new AbortController();setBusy(true);$('progress-text').textContent='正在查找公开资料并整理出处…';$('suggestions').replaceChildren();try{const response=await fetch('/api/agent/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:text,history:researchHistory.slice(-12)}),signal:requestController.signal});let result;try{result=await response.json();}catch{throw new Error('服务暂未返回有效结果，请稍后重试。');}if(!response.ok)throw new Error(result.error?.message||result.message||'本次查找未完成，请稍后重试。');if(version!==requestVersion)return {status:'discarded'};if(typeof result.answer!=='string')throw new Error('这次结果不完整，请重试。');message('assistant',result.answer,result.sources||[]);researchHistory.push({role:'user',content:text},{role:'assistant',content:result.answer});conversationStage='research';const count=updateResearchMap(result);const sourceMap=new Map((result.sources||[]).map(s=>[s.id,s]));for(const item of result.clues||[]){const sources=(item.sourceIds||[]).map(id=>sourceMap.get(id)).filter(Boolean);clue(item.title,item.summary,item.id,sources);}if(result.sources?.length){const section=document.createElement('section');section.className='sources-list';const heading=document.createElement('h3');heading.textContent='本次查阅的来源';section.append(heading);for(const source of result.sources)linkSource(section,source);$('conversation').append(section);}if(result.gaps?.length){const p=document.createElement('p');p.className='gap-note';p.textContent='仍待确认：'+result.gaps.join('；');$('conversation').append(p);}if(result.followup?.question)message('assistant',result.followup.question);suggestions((result.followup?.options||[]).slice(0,4).map(label=>[label,'']));if(count){$('map-toast').textContent='新增 '+count+' 处有来源的地点，点击「历史地图」查看。';$('map-toast').hidden=false;}scrollThread();return {status:'complete',places:count};}catch(error){if(version!==requestVersion)return {status:'discarded'};if(error.name==='AbortError')return {status:'cancelled'};message('assistant',error.message||'暂时无法连接溯源服务，请稍后再试。');const retry=document.createElement('button');retry.className='text-button';retry.type='button';retry.textContent='重试这次查找';retry.addEventListener('click',()=>{if(!busy){retry.remove();sendResearch(text,false);}});$('conversation').append(retry);scrollThread();return {status:'error'};}finally{if(version===requestVersion){requestController=null;setBusy(false);}}}
async function submitQuestion(text){if(typeof text!=='string'||!text.trim()||text.length>600){$('form-error').textContent='写一点你想了解的问题，再开始探索。';$('form-error').hidden=false;return {status:'invalid'};}if(busy)return {status:'busy'};text=text.trim();$('form-error').hidden=true;if(conversationMode==='live')return sendResearch(text);message('user',text);const negative=/不姓阮|不是阮|并非阮|姓[陈张李王刘赵黄杨吴周徐孙马朱胡郭何林高郑]/.test(text);if(query?.demo&&!negative&&['generation','candidate'].includes(conversationStage)&&/英.?士.?班|班.?家.?国/.test(text)){$('conversation').lastElementChild.remove();act('dayuan',text);}else if(query?.demo&&!negative&&['generation','candidate'].includes(conversationStage)&&/英.?士.?中|中.?州.?启/.test(text)){$('conversation').lastElementChild.remove();act('yangxin',text);}else if(query?.demo&&conversationStage==='generation'&&/^(暂时)?(不知道|不记得|不清楚)/.test(text)){$('conversation').lastElementChild.remove();act('unknown',text);}else if(query?.demo&&!negative&&/江西|迁徙|迁来|乐平/.test(text)){$('conversation').lastElementChild.remove();act('route',text);}else if(query?.demo&&!negative&&/阮籍|竹林|堂号/.test(text)){$('conversation').lastElementChild.remove();act('culture',text);}else{message('assistant','当前是阮氏固定示例，不能用它判断你家的来历。可以选择下方示例体验流程，或切换「真实溯源」查询自己的线索。');if(negative){query=null;branch=null;conversationStage='welcome';useDemoMap();}welcomeSuggestions();}setBusy(false);return {stage:conversationStage,demoOnly:true};}
$('chat-form').addEventListener('submit',e=>{e.preventDefault();if(busy)return;const text=$('question').value;if(!text.trim()){submitQuestion(text);return;}submitQuestion(text);if(!busy||conversationMode==='live'){$('question').value='';$('question').style.height='';}});$('question').addEventListener('input',()=>{$('form-error').hidden=true;$('question').style.height='auto';$('question').style.height=Math.min($('question').scrollHeight,160)+'px';});$('question').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&!e.ctrlKey&&!e.metaKey){e.preventDefault();$('chat-form').requestSubmit();}});$('reset-chat').addEventListener('click',resetConversation);$('cancel-query').addEventListener('click',()=>cancelResearch());$('mode-demo').addEventListener('click',()=>switchMode('demo'));$('mode-live').addEventListener('click',()=>switchMode('live'));
resetConversation();
fetch('/api/agent/status').then(r=>{if(!r.ok)throw new Error('status unavailable');return r.json();}).then(status=>{agentStatus=status;if(status.available&&!modeTouched&&conversationStage==='welcome'){conversationMode='live';resetConversation();}else updateServiceNotice();}).catch(()=>{agentStatus={available:false};updateServiceNotice();});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'ask_family_history',description:'向当前选择的模式提问；真实模式通过服务端检索，示例模式使用预置材料。',inputSchema:{type:'object',properties:{question:{type:'string',minLength:1,maxLength:600}},required:['question'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>submitQuestion(input?.question)},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
